from collections import deque
def flood(start, allowed):
    H,W=len(start),len(start[0]); seen=set(); q=deque()
    for r in range(H):
        for c in range(W):
            if start[r][c] in allowed:
                q.append((r,c)); seen.add((r,c))
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    while q:
        r,c=q.popleft()
        for dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and start[nr][nc] in allowed and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen
