import numpy as np
def comps_of(grid,val):
    H,W=len(grid),len(grid[0]); seen=set(); res=[]
    for s in [(r,c) for r in range(H) for c in range(W) if grid[r][c]==val]:
        if s in seen: continue
        st=[s]; cc=set()
        while st:
            r_,c_=st.pop()
            if (r_,c_) in cc: continue
            cc.add((r_,c_)); seen.add((r_,c_))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r_+dr,c_+dc)
                    if 0<=n[0]<H and 0<=n[1]<W and grid[n[0]][n[1]]==val and n not in cc: st.append(n)
        res.append(cc)
    return res
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bgg=max(cnt,key=lambda v:cnt[v])
    vals=[v for v in cnt if v!=bgg]
    seedc=min(vals,key=lambda v:cnt[v])
    big=max(comps_of(g,seedc),key=len)
    mr=min(r for r,c in big); mc=min(c for r,c in big)
    P=sorted((r-mr,c-mc) for r,c in big)
    ok=set()
    for r in range(H):
        for c in range(W):
            if any(r+a<0 or c+b<0 for a,b in P): continue
            S=[(r+a,c+b) for a,b in P]
            if all(0<=S[x][0]<H and 0<=S[x][1]<W and g[S[x][0]][S[x][1]]==0 for x in range(len(P))):
                ok|=set(S)
    out=[row[:] for row in g]
    for q in ok: out[q[0]][q[1]]=seedc
    return out
